function roundKey() {
  return Math.floor(Date.now() / 60000)
}

function sign(value: string) {
  return createHash('sha256').update(value + SECRET_KEY).digest('hex')
}

/**
 * Token format: `<id>:<b64username>.<hmac>`
 * Encoding the username lets us silently re-create the player record
 * when the in-memory store is wiped (Vercel cold-start / dev HMR).
 */
function makeToken(id: string, username: string) {
  const b64 = Buffer.from(username).toString('base64url')
  const payload = `${id}:${b64}`
  return `${payload}.${sign(payload)}`
}

async function player() {
  try {
    const cookieStore = await cookies()
    const token = cookieStore.get(COOKIE)?.value
    if (!token) return null

    const dotIdx = token.lastIndexOf('.')
    if (dotIdx === -1) return null
    const payload = token.slice(0, dotIdx)
    const sig = token.slice(dotIdx + 1)
    if (sig !== sign(payload)) return null

    // Support both old format (id) and new format (id:b64username)
    const colonIdx = payload.indexOf(':')
    const id = colonIdx === -1 ? payload : payload.slice(0, colonIdx)
    const b64username = colonIdx === -1 ? '' : payload.slice(colonIdx + 1)

    let p = await getPlayer(id)

    // Self-heal: if the store was wiped, re-create the player from the token
    if (!p && b64username) {
      try {
        const username = Buffer.from(b64username, 'base64url').toString('utf8')
        const norm = username.toLowerCase()
        p = await upsertPlayer(username, norm)
        // Preserve the original id if possible (memory store increments)
      } catch {
        return null
      }
    }

    return p ? { id: p.id, username: p.username, score: p.score } : null
  } catch {
    return null
  }
}


async function makeQuestion(key: number) {
  const randomIndex = Math.floor(Math.random() * deloitteFallbackBank.length)
  const base = deloitteFallbackBank[randomIndex]
  const apiKey =
    process.env.GEMINI_API_KEY ||
    process.env.GOOGLE_GENERATIVE_AI_API_KEY ||
    process.env.GOOGLE_AI_API_KEY

  if (!apiKey) return base

  try {
    const google = createGoogleGenerativeAI({ apiKey })
    const modelName = process.env.GEMINI_MODEL || 'gemini-3.6-flash'
    const { text } = await generateText({
      model: google(modelName),
      prompt: `You are an expert assessment designer creating aptitude test questions specifically tailored for the Deloitte Campus Placement & National Level Assessment (NLA / Deloitte Placement Rounds).

Generate one original, realistic question for assessment round #${key}.

Alternate across these core Deloitte testing pillars based on round number:
1. "Deloitte Quants": Time & Work, Time Speed Distance, Profit & Loss, Percentages, Simple & Compound Interest, Mixtures & Alligations, Permutations & Combinations, Probability, Number Properties.
2. "Deloitte Logical": Syllogisms, Blood Relations, Coding-Decoding, Linear/Circular Seating Arrangements, Direction Sense, Data Sufficiency, Statement & Assumptions.
3. "Deloitte Verbal": Sentence Correction, Spotting Errors, Vocabulary in Context (Synonyms/Antonyms), Para Jumbles, Prepositions, Subject-Verb Agreement.

Rules:
- Difficulty should match actual Deloitte hiring rounds (mostly Medium, occasionally Hard).
- Provide 4 distinct, plausible options.
- Give a concise, step-by-step mathematical/logical explanation.
- Return ONLY valid JSON with:
  - "question": string
  - "options": array of exactly 4 strings
  - "correct": integer 0-3
  - "explanation": string
  - "category": "Deloitte Quants" | "Deloitte Logical" | "Deloitte Verbal"
  - "difficulty": "Easy" | "Medium" | "Hard"
`,
      temperature: 0.85,
    })

    const cleanedText = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim()
    const parsed = JSON.parse(cleanedText)
    if (
      typeof parsed.question === 'string' &&
      Array.isArray(parsed.options) &&
      parsed.options.length === 4 &&
      Number.isInteger(parsed.correct)
    ) {
      return parsed
    }
  } catch (err) {
    console.error('[Quiz AI] Error generating question with Google Gemini:', err)
    /* fallback keeps rounds available */
  }
  return base
}

export async function OPTIONS() {
  return new NextResponse(null, {
    status: 200,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Requested-With',
      'Access-Control-Allow-Credentials': 'true',
    },
  })
}

export async function GET() {
  const p = await player()
  if (!p) {
    return NextResponse.json({ signedIn: false })
  }

  const key = roundKey()
  const start = new Date(key * 60000)
  const end = new Date((key + 1) * 60000)

  let r = await getRoundByKey(key)
  if (!r) {
    const q = await makeQuestion(key)
    r = await saveRound({
      round_key: key,
      starts_at: start,
      ends_at: end,
      question: q.question,
      options: q.options,
      correct_index: q.correct,
      explanation: q.explanation || '',
      category: q.category || 'Deloitte Quants',
      difficulty: q.difficulty || 'Medium',
    })
  }

  const answer = await getPlayerAnswer(p.id, r.id)
  const leaderboard = await getLeaderboard()

  return NextResponse.json({
    signedIn: true,
    player: p,
    round: {
      id: r.id,
      round_key: r.round_key,
      question: r.question,
      options: r.options,
      explanation: r.explanation,
      category: r.category,
      difficulty: r.difficulty,
      starts_at: r.starts_at,
      ends_at: r.ends_at,
      answered: !!answer,
      result: answer ?? null,
    },
    leaderboard,
    now: Date.now(),
  })
}

export async function POST(req: Request) {
  try {
    const body = await req.json()
    const { username, answer } = body

    // Username entry / Sign in step
    if (username !== undefined) {
      const clean = String(username).trim().replace(/[^a-zA-Z0-9_ -]/g, '').slice(0, 20)
      if (clean.length < 2) {
        return NextResponse.json({ error: 'Use at least 2 characters' }, { status: 400 })
      }

      // Check if the current request already has a valid session — if so, re-use it
      // (prevents accidental account switch on re-join with same username)
      const existingPlayer = await player()
      if (existingPlayer) {
        const token = makeToken(existingPlayer.id, existingPlayer.username)
        const res = NextResponse.json({ ok: true, player: existingPlayer })
        res.cookies.set(COOKIE, token, {
          httpOnly: true,
          sameSite: 'lax',
          secure: process.env.NODE_ENV === 'production',
          maxAge: 60 * 60 * 24 * 30,
          path: '/',
        })
        return res
      }

      // Find a unique normalized username to avoid giving this new user
      // access to an existing player's account
      let finalClean = clean
      let norm = clean.toLowerCase()
      const existingById = await getPlayerByNorm(norm)
      if (existingById) {
        // Username is taken — append a random 4-digit suffix to make it unique
        const suffix = Math.floor(1000 + Math.random() * 9000)
        finalClean = (clean.slice(0, 15) + '_' + suffix)
        norm = finalClean.toLowerCase()
      }

      const pl = await upsertPlayer(finalClean, norm)
      const token = makeToken(pl.id, pl.username)
      const res = NextResponse.json({ ok: true, player: { id: pl.id, username: pl.username, score: pl.score } })
      res.cookies.set(COOKIE, token, {
        httpOnly: true,
        sameSite: 'lax',
        secure: process.env.NODE_ENV === 'production',
        maxAge: 60 * 60 * 24 * 30,
        path: '/',
      })
      return res
    }

    const p = await player()
    if (!p) {
      return NextResponse.json({ error: 'Sign in required' }, { status: 401 })
    }

    const key = roundKey()
    const r = await getRoundByKey(key)
    if (!r || Date.now() >= new Date(r.ends_at).getTime()) {
      return NextResponse.json({ error: 'Round is locked' }, { status: 400 })
    }

    const idx = Number(answer)
    if (!Number.isInteger(idx) || idx < 0 || idx > 3) {
      return NextResponse.json({ error: 'Invalid answer' }, { status: 400 })
    }

    const correct = idx === r.correct_index
    await submitAnswer(p.id, r.id, idx, correct)

    return NextResponse.json({ ok: true, correct })
  } catch (err: any) {
    console.error('Error in POST /api/quiz:', err)
    return NextResponse.json({ error: err?.message || 'Server error' }, { status: 500 })
  }
}

export async function DELETE() {
  const res = NextResponse.json({ ok: true })
  res.cookies.delete(COOKIE)
  return res
}
